// Example packs for an empty store. The "Toy Box" pack is hand-made (committed); the others are
// built at startup from the disc's maps and mission table (public/assets/data, generated by
// tools/build_data.py and never committed), so they only appear where that data exists.

import { existsSync, readFileSync } from 'node:fs'
import { LEVEL_H, LEVEL_W, type EnemySlot, type LevelDef, type LevelPack } from '../../src/levels/format'
import { checkPack, normalizePack } from '../../src/levels/check'
import { getRow, insertPack, updatePack } from './store'

/**
 * ASCII level rows: `.` empty, `1`-`7` wood stack (201-207), `a`-`g` cork stack (101-107),
 * `O` hole, `P` `Q` `R` `S` players 1-4, `A`-`L` enemy slots 0-11.
 */
export function fromAscii(rows: string[]): number[][] {
  if (rows.length !== LEVEL_H || rows.some((r) => r.length !== LEVEL_W)) throw new Error('ascii level must be 22 x 17')
  return rows.map((r) =>
    [...r].map((ch) => {
      if (ch >= '1' && ch <= '7') return 200 + Number(ch)
      if (ch >= 'a' && ch <= 'g') return 100 + ch.charCodeAt(0) - 96
      if (ch === 'O') return 200
      const p = 'PQRS'.indexOf(ch)
      if (p >= 0) return 300 + p
      const e = 'ABCDEFGHIJKL'.indexOf(ch)
      if (e >= 0) return 400 + e
      return 0
    }),
  )
}

