type RawMission = { slots1P: number[]; map1P: [number, number]; bonus: number }
type RawMap = { facing: [number, number]; cells: number[][] }

/** a disc mission slot: 1-9 a type, two digits `ab` a random type in a..b */
const slot = (v: number): EnemySlot => (v < 10 ? v : [Math.trunc(v / 10), v % 10])

function discPack(maps: Record<string, RawMap>, missions: RawMission[], name: string, description: string, picks: number[], lives = 3): LevelPack | null {
  const levels: LevelDef[] = []
  for (const mi of picks) {
    const m = missions[mi - 1]
    const map = maps[`P1_${String(m?.map1P[0]).padStart(2, '0')}_16_9`]
    if (!m || !map) return null
    const enemies = m.slots1P.map(slot)
    levels.push({
      v: 1,
      name: `Mission ${mi}`,
      // the maps are shared between missions: spawns without a tank in this mission are dropped
      cells: map.cells.map((r) => r.map((c) => (c >= 400 && c < 412 && !enemies[c - 400] ? 0 : c))),
      enemies,
      facing: map.facing,
      bonus: m.bonus > 0 || undefined,
    })
  }
  return { v: 1, name, description, lives, levels }
}

export function seedStore() {
  const packs: { id: string; pack: LevelPack }[] = [{ id: 'toy-box', pack: TOY_BOX }]
  const dir = process.env.GAME_DATA_DIR ?? `${import.meta.dir}/../../public/assets/data`
  if (existsSync(`${dir}/maps.json`) && existsSync(`${dir}/params.json`)) {
    try {
      const maps = JSON.parse(readFileSync(`${dir}/maps.json`, 'utf8')) as Record<string, RawMap>
      const missions = (JSON.parse(readFileSync(`${dir}/params.json`, 'utf8')) as { missions: RawMission[] }).missions
      const add = (id: string, p: LevelPack | null) => p && packs.push({ id, pack: p })
      add('classic-highlights', discPack(maps, missions, 'Classic Highlights', 'Eight memorable arenas from the original campaign, with their original tanks.', [3, 6, 9, 13, 14, 17, 18, 30]))
      add('classic-gauntlet', discPack(maps, missions, 'Late Game Gauntlet', 'Missions from the gold-medal half of the campaign: Violet, White and Black tanks.', [41, 51, 61, 71, 75, 85], 5))
      add('classic-mazes', discPack(maps, missions, 'Wood & Cork Mazes', 'The twistiest maze layouts of the original game.', [10, 11, 16, 19, 25]))
    } catch (e) {
      console.warn('levels: disc seed packs skipped:', e)
    }
  }
  for (const { id, pack } of packs) {
    const row = getRow(id)
    // a seed pack already in the store: refreshed when its text changes here (plays and ratings stay)
    if (row) {
      if (row.seed && (row.name !== pack.name || row.description !== (pack.description ?? ''))) updatePack(id, normalizePack(pack), row.author)
      continue
    }
    const c = checkPack(pack)
    if (c.errors.length) {
      console.warn(`levels: seed ${id} invalid:`, c.errors)
      continue
    }
    insertPack({ id, pack: normalizePack(pack), author: 'Tanks! team', owner: null, seed: true })
  }
}
